public void increment(final double x, final double y) {
    n++;
    final double sx = MathUtils.shortfall(x, meanX);
    final double sy = MathUtils.shortfall(y, meanY);
    meanX -= sx / n;
    meanY -= sy / n;
    covarianceNumerator += ((n - 1.0) / n) * sx * sy;
}

